window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["minimax"]={html:"<div class=\"own-minimax\">\n  <div class=\"mm-promo\">\n    <span>Invite and earn &mdash; rewards for both</span>\n    <a href=\"#pricing\">Claim yours &rarr;</a>\n  </div>\n\n  <header class=\"mm-nav\">\n    <a class=\"mm-logo\" href=\"#\" aria-label=\"Northwind home\"><span class=\"mm-logo-mark\" aria-hidden=\"true\"></span>Northwind</a>\n    <nav class=\"mm-nav-links\" aria-label=\"Primary\">\n      <a href=\"#matrix\">Models</a>\n      <a href=\"#product\">Product</a>\n      <a href=\"#docs\">API</a>\n      <a href=\"#pricing\">Company</a>\n    </nav>\n    <div class=\"mm-nav-right\">\n      <a class=\"mm-btn mm-btn-ghost\" href=\"#\">Log in</a>\n      <a class=\"mm-btn mm-btn-primary\" href=\"#pricing\">Contact us</a>\n      <button class=\"mm-hamburger\" type=\"button\" aria-label=\"Menu\" data-mm-menu>\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 7h16M4 12h16M4 17h16\"/></svg>\n      </button>\n    </div>\n  </header>\n\n  <section class=\"mm-hero\" aria-labelledby=\"mmHeroH\">\n    <span class=\"mm-badge mm-badge-new\">New</span>\n    <h1 id=\"mmHeroH\" class=\"mm-h1\">Operations with<br>everyone.</h1>\n    <p class=\"mm-hero-sub\">Northwind models your warehouses, regions and pricing in one stack &mdash;\n      fast, legible and ready to ship to the whole team.</p>\n    <div class=\"mm-hero-cta\">\n      <a class=\"mm-btn mm-btn-primary mm-btn-lg\" href=\"#matrix\">Start building</a>\n      <a class=\"mm-btn mm-btn-secondary mm-btn-lg\" href=\"#docs\">Read the docs</a>\n    </div>\n    <div class=\"mm-terminal\" aria-hidden=\"true\">\n      <div class=\"mm-term-head\"><span class=\"mm-term-dot\"></span><span class=\"mm-term-dot\"></span><span class=\"mm-term-dot\"></span><span class=\"mm-term-name\">northwind &middot; board.py</span></div>\n      <pre class=\"mm-term-body\"><span class=\"mm-c\"># build a throughput board</span>\n<span class=\"mm-k\">from</span> northwind <span class=\"mm-k\">import</span> Board\n\nboard = Board(<span class=\"mm-s\">\"north-loop\"</span>)\nboard.add_regions(<span class=\"mm-s\">\"nordics\"</span>, <span class=\"mm-s\">\"apac\"</span>)\nboard.metric(<span class=\"mm-s\">\"cycle_time\"</span>, window=<span class=\"mm-s\">\"7d\"</span>)\nboard.publish()</pre>\n      <div class=\"mm-term-foot\"><span class=\"mm-dot\"></span> 4 regions &middot; 1 board &middot; 0.8s</div>\n    </div>\n  </section>\n\n  <section id=\"matrix\" class=\"mm-sec\" aria-labelledby=\"mmMatrixH\">\n    <div class=\"mm-sec-head\">\n      <h2 id=\"mmMatrixH\" class=\"mm-h2\">The full-stack matrix.</h2>\n      <p class=\"mm-lead\">Each surface gets its own identity. Colour is the fastest way to know\n        where you are.</p>\n    </div>\n    <div class=\"mm-cards\">\n      <article class=\"mm-pcard mm-pcard-coral\">\n        <span class=\"mm-badge mm-badge-new\">Live</span>\n        <p class=\"mm-pcard-name\">Throughput</p>\n        <p class=\"mm-pcard-tag\">Dock, line and cycle time in one board.</p>\n      </article>\n      <article class=\"mm-pcard mm-pcard-magenta\">\n        <p class=\"mm-pcard-name\">Regions</p>\n        <p class=\"mm-pcard-tag\">Every territory, one comparison table.</p>\n      </article>\n      <article class=\"mm-pcard mm-pcard-blue\">\n        <p class=\"mm-pcard-name\">Pricing</p>\n        <p class=\"mm-pcard-tag\">Margin and tier mix, by channel.</p>\n      </article>\n      <article class=\"mm-pcard mm-pcard-purple\">\n        <p class=\"mm-pcard-name\">Forecast</p>\n        <p class=\"mm-pcard-tag\">Demand signals before the doors open.</p>\n      </article>\n    </div>\n    <div class=\"mm-ai-grid\">\n      <a class=\"mm-tile\" href=\"#product\">\n        <span class=\"mm-tile-art mm-art-a\" aria-hidden=\"true\"></span>\n        <h3 class=\"mm-tile-title\">Agent</h3>\n        <p class=\"mm-tile-desc\">Ask the board a question in plain language.</p>\n      </a>\n      <a class=\"mm-tile\" href=\"#product\">\n        <span class=\"mm-tile-art mm-art-b\" aria-hidden=\"true\"></span>\n        <h3 class=\"mm-tile-title\">Digest</h3>\n        <p class=\"mm-tile-desc\">A weekly summary written for leadership.</p>\n      </a>\n      <a class=\"mm-tile\" href=\"#product\">\n        <span class=\"mm-tile-art mm-art-c\" aria-hidden=\"true\"></span>\n        <h3 class=\"mm-tile-title\">Alerts</h3>\n        <p class=\"mm-tile-desc\">Route a threshold to the right person.</p>\n      </a>\n      <a class=\"mm-tile\" href=\"#product\">\n        <span class=\"mm-tile-art mm-art-d\" aria-hidden=\"true\"></span>\n        <h3 class=\"mm-tile-title\">Exports</h3>\n        <p class=\"mm-tile-desc\">Screenshots, PDFs and scheduled email.</p>\n      </a>\n    </div>\n  </section>\n\n  <section id=\"product\" class=\"mm-sec\" aria-labelledby=\"mmProdH\">\n    <div class=\"mm-sec-head\">\n      <h2 id=\"mmProdH\" class=\"mm-h2\">Built for the operations desk.</h2>\n    </div>\n    <div class=\"mm-feature-grid\">\n      <article class=\"mm-card\">\n        <span class=\"mm-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 19V5M4 19h16M8 15l3-4 3 2 4-6\"/></svg></span>\n        <h3 class=\"mm-card-title\">One metric language</h3>\n        <p class=\"mm-card-desc\">Define throughput once and every board reads it the same way.</p>\n      </article>\n      <article class=\"mm-card\">\n        <span class=\"mm-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"3\"/><path d=\"M4 10h16M10 10v10\"/></svg></span>\n        <h3 class=\"mm-card-title\">Composable regions</h3>\n        <p class=\"mm-card-desc\">Slice by territory, channel or week without rebuilding.</p>\n      </article>\n      <article class=\"mm-card\">\n        <span class=\"mm-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"8\"/><path d=\"M12 8v4l3 2\"/></svg></span>\n        <h3 class=\"mm-card-title\">Scheduled</h3>\n        <p class=\"mm-card-desc\">Boards refresh before the standup and land in inboxes.</p>\n      </article>\n      <article class=\"mm-card\">\n        <span class=\"mm-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 3l8 4v5c0 4.4-3 8-8 9-5-1-8-4.6-8-9V7z\"/></svg></span>\n        <h3 class=\"mm-card-title\">Governed</h3>\n        <p class=\"mm-card-desc\">Row-level access keeps every region visible to the right desk.</p>\n      </article>\n    </div>\n  </section>\n\n  <section class=\"mm-stats\" aria-labelledby=\"mmStatsH\">\n    <h2 id=\"mmStatsH\" class=\"mm-sr\">Northwind by the numbers</h2>\n    <div class=\"mm-stat-row\">\n      <div class=\"mm-stat\"><b>214,000+</b><span>Teams and developers</span></div>\n      <div class=\"mm-stat\"><b>190</b><span>Countries served</span></div>\n      <div class=\"mm-stat\"><b>99.98%</b><span>Board uptime</span></div>\n      <div class=\"mm-stat\"><b>41 ms</b><span>Median query time</span></div>\n    </div>\n  </section>\n\n  <section id=\"docs\" class=\"mm-sec mm-docs\" aria-labelledby=\"mmDocsH\">\n    <div class=\"mm-docs-grid\">\n      <nav class=\"mm-docs-side\" aria-label=\"Docs\">\n        <p class=\"mm-side-head\">Primitives</p>\n        <a href=\"#\" class=\"mm-side-link is-active\">Boards</a>\n        <a href=\"#\" class=\"mm-side-link\">Metrics</a>\n        <a href=\"#\" class=\"mm-side-link\">Regions</a>\n        <p class=\"mm-side-head\">Reference</p>\n        <a href=\"#\" class=\"mm-side-link\">API keys</a>\n        <a href=\"#\" class=\"mm-side-link\">Webhooks</a>\n      </nav>\n      <div class=\"mm-docs-body\">\n        <h2 id=\"mmDocsH\" class=\"mm-h3\">Boards</h2>\n        <p class=\"mm-prose\">A board is the unit of work in Northwind. It owns a set of metrics, a set of\n          regions and a schedule. Create one, add regions, publish it &mdash; the API is built so the\n          happy path takes four lines.</p>\n        <div class=\"mm-code\">\n          <div class=\"mm-code-head\"><span>Python</span><button type=\"button\" class=\"mm-copy\">Copy code</button></div>\n          <pre class=\"mm-code-body\"><span class=\"mm-k\">import</span> northwind <span class=\"mm-k\">as</span> nw\n\nboard = nw.Board(<span class=\"mm-s\">\"cycle-time\"</span>)\nboard.metric(<span class=\"mm-s\">\"cycle_time\"</span>, window=<span class=\"mm-s\">\"7d\"</span>)\nboard.publish()</pre>\n        </div>\n        <table class=\"mm-table\">\n          <caption class=\"mm-sr\">Board properties</caption>\n          <thead><tr><th scope=\"col\">Property</th><th scope=\"col\">Type</th><th scope=\"col\">Description</th></tr></thead>\n          <tbody>\n            <tr><td><code>name</code></td><td><span class=\"mm-badge-code\">string</span></td><td>Human-readable board name.</td></tr>\n            <tr><td><code>regions</code></td><td><span class=\"mm-badge-code\">string[]</span></td><td>Territory keys to include.</td></tr>\n            <tr><td><code>schedule</code></td><td><span class=\"mm-badge-code\">cron</span></td><td>Refresh cadence. Defaults to daily.</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <aside class=\"mm-docs-toc\" aria-label=\"On this page\">\n        <p class=\"mm-side-head\">On this page</p>\n        <a href=\"#docs\" class=\"mm-toc-link is-active\">Overview</a>\n        <a href=\"#docs\" class=\"mm-toc-link\">Creating a board</a>\n        <a href=\"#docs\" class=\"mm-toc-link\">Properties</a>\n      </aside>\n    </div>\n  </section>\n\n  <section id=\"pricing\" class=\"mm-sec\" aria-labelledby=\"mmPriceH\">\n    <div class=\"mm-sec-head mm-center\">\n      <h2 id=\"mmPriceH\" class=\"mm-h2\">Token plans.</h2>\n      <p class=\"mm-lead\">Start free. Scale when the board room asks for more.</p>\n    </div>\n    <div class=\"mm-tabs\" role=\"tablist\" aria-label=\"Plans\">\n      <button class=\"mm-pill is-active\" role=\"tab\" aria-selected=\"true\" type=\"button\" data-mm-tab>Token plan</button>\n      <button class=\"mm-pill\" role=\"tab\" aria-selected=\"false\" type=\"button\" data-mm-tab>Annual</button>\n    </div>\n    <div class=\"mm-price-grid\">\n      <article class=\"mm-price-card\">\n        <h3 class=\"mm-card-title\">Starter</h3>\n        <p class=\"mm-price\">$0<span>/mo</span></p>\n        <ul class=\"mm-price-list\"><li>1 board</li><li>2 regions</li><li>Community support</li></ul>\n        <a class=\"mm-btn mm-btn-tertiary mm-btn-block\" href=\"#\">Start free</a>\n      </article>\n      <article class=\"mm-price-card mm-price-featured\">\n        <span class=\"mm-badge mm-badge-beta\">Most popular</span>\n        <h3 class=\"mm-card-title\">Team</h3>\n        <p class=\"mm-price\">$49<span>/mo</span></p>\n        <ul class=\"mm-price-list\"><li>20 boards</li><li>Unlimited regions</li><li>Scheduled digests</li></ul>\n        <a class=\"mm-btn mm-btn-primary mm-btn-block\" href=\"#\">Choose Team</a>\n      </article>\n      <article class=\"mm-price-card\">\n        <h3 class=\"mm-card-title\">Scale</h3>\n        <p class=\"mm-price\">Custom</p>\n        <ul class=\"mm-price-list\"><li>Unlimited boards</li><li>Governed access</li><li>Priority support</li></ul>\n        <a class=\"mm-btn mm-btn-tertiary mm-btn-block\" href=\"#\">Talk to us</a>\n      </article>\n    </div>\n  </section>\n\n  <section class=\"mm-cta\" aria-labelledby=\"mmCtaH\">\n    <h2 id=\"mmCtaH\" class=\"mm-h2\">Ship your first board today.</h2>\n    <a class=\"mm-btn mm-btn-tertiary mm-btn-lg\" href=\"#\">Join now</a>\n  </section>\n\n  <footer class=\"mm-foot\">\n    <div class=\"mm-foot-top\">\n      <div class=\"mm-foot-brand\">\n        <span class=\"mm-logo-mark\" aria-hidden=\"true\"></span>\n        <span>Northwind</span>\n        <p class=\"mm-foot-tag\">Intelligence with everyone.</p>\n      </div>\n      <div class=\"mm-foot-grid\">\n        <div class=\"mm-foot-col\"><h3>Research</h3><a href=\"#\">Overview</a><a href=\"#\">Papers</a></div>\n        <div class=\"mm-foot-col\"><h3>Product</h3><a href=\"#\">Boards</a><a href=\"#\">Agent</a></div>\n        <div class=\"mm-foot-col\"><h3>API</h3><a href=\"#\">Reference</a><a href=\"#\">Status</a></div>\n        <div class=\"mm-foot-col\"><h3>Company</h3><a href=\"#\">About</a><a href=\"#\">News</a></div>\n      </div>\n    </div>\n    <div class=\"mm-foot-bottom\">\n      <span>&copy; 2026 Northwind Analytics</span>\n      <span class=\"mm-foot-links\"><a href=\"#\">Privacy</a><a href=\"#\">Terms</a><a href=\"#\">Security</a></span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — own layout in the MiniMax design language ══════════════════\n   Stark black-and-white canvas broken open by saturated gradient product cards,\n   DM Sans at 80px hero with -2px tracking, black-pill buttons everywhere, a black\n   promo banner, and a 3-column docs surface (sidebar / prose / TOC). */\n\n.own-minimax {\n  --primary: #0a0a0a;\n  --charcoal: #222222;\n  --canvas: #ffffff;\n  --surface: #f7f8fa;\n  --surface-soft: #f2f3f5;\n  --hairline: #e5e7eb;\n  --hairline-soft: #eaecf0;\n  --ink: #0a0a0a;\n  --charcoal-text: #222222;\n  --slate: #45515e;\n  --steel: #5f5f5f;\n  --stone: #8e8e93;\n  --muted: #a8aab2;\n  --coral: #ff5530;\n  --magenta: #ea5ec1;\n  --blue: #1456f0;\n  --purple: #a855f7;\n  --blue-deep: #1d4ed8;\n  --blue-200: #bfdbfe;\n  --success-bg: #e8ffea;\n  --success-text: #1ba673;\n  --font: 'DM Sans', Inter, 'Helvetica Neue', Helvetica, Arial, sans-serif;\n  --mono: 'SF Mono', Menlo, Consolas, monospace;\n  --gut: clamp(20px, 5cqi, 48px);\n\n  position: relative;\n  border-radius: 13px;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--font);\n  font-size: 16px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n}\n.own-minimax *,\n.own-minimax *::before,\n.own-minimax *::after { box-sizing: border-box; }\n.own-minimax :focus-visible { outline: 2px solid var(--blue-deep); outline-offset: 2px; border-radius: 6px; }\n.own-minimax .mm-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }\n\n/* ── type ────────────────────────────────────────────────────────────────── */\n.own-minimax .mm-h1 { font-weight: 600; font-size: clamp(42px, 6.6cqi, 80px); line-height: 1.1; letter-spacing: -2px; }\n.own-minimax .mm-h2 { font-weight: 600; font-size: clamp(28px, 3.4cqi, 40px); line-height: 1.2; letter-spacing: -1px; }\n.own-minimax .mm-h3 { font-weight: 600; font-size: 24px; line-height: 1.3; }\n.own-minimax .mm-lead { color: var(--steel); font-size: 18px; line-height: 1.5; max-width: 56ch; }\n.own-minimax .mm-prose { color: var(--charcoal-text); font-size: 16px; line-height: 1.7; margin: 10px 0 20px; }\n\n/* ── buttons ────────────────────────────────────────────────────────────── */\n.own-minimax .mm-btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  height: 42px; padding: 0 24px; border: 1px solid transparent; border-radius: 9999px; cursor: pointer;\n  font-family: var(--font); font-size: 14px; font-weight: 600; line-height: 1.4;\n  text-decoration: none; transition: background-color .15s, border-color .15s;\n}\n.own-minimax .mm-btn-primary { background: var(--primary); color: #fff; }\n.own-minimax .mm-btn-primary:active { background: var(--charcoal); }\n.own-minimax .mm-btn-secondary { background: transparent; color: var(--ink); border-color: var(--ink); }\n.own-minimax .mm-btn-tertiary { background: var(--canvas); color: var(--ink); border-color: var(--hairline); }\n.own-minimax .mm-btn-ghost { background: transparent; color: var(--ink); }\n.own-minimax .mm-btn-lg { height: 48px; padding: 0 30px; }\n.own-minimax .mm-btn-block { width: 100%; }\n\n/* ── promo + nav ─────────────────────────────────────────────────────────── */\n.own-minimax .mm-promo { display: flex; align-items: center; justify-content: center; gap: 14px; flex-wrap: wrap; background: var(--primary); color: #fff; padding: 10px 24px; font-size: 14px; font-weight: 500; }\n.own-minimax .mm-promo a { color: #fff; text-decoration: underline; }\n.own-minimax .mm-nav { position: sticky; top: 68px; z-index: 30; display: flex; align-items: center; gap: 24px; padding: 12px var(--gut); background: rgba(255,255,255,.92); backdrop-filter: blur(10px); border-bottom: 1px solid var(--hairline-soft); }\n.own-minimax .mm-logo { display: inline-flex; align-items: center; gap: 10px; text-decoration: none; color: var(--ink); font-weight: 600; font-size: 18px; letter-spacing: -.4px; }\n.own-minimax .mm-logo-mark { width: 26px; height: 26px; border-radius: 8px; background: var(--primary); display: inline-block; }\n.own-minimax .mm-nav-links { display: flex; align-items: center; gap: 26px; margin-left: 8px; }\n.own-minimax .mm-nav-links a { color: var(--charcoal-text); text-decoration: none; font-size: 14px; font-weight: 500; }\n.own-minimax .mm-nav-links a:hover { color: var(--ink); }\n.own-minimax .mm-nav-right { margin-left: auto; display: flex; align-items: center; gap: 8px; }\n.own-minimax .mm-hamburger { display: none; width: 42px; height: 42px; align-items: center; justify-content: center; border: 1px solid var(--hairline); border-radius: 9999px; background: var(--canvas); cursor: pointer; }\n.own-minimax .mm-hamburger svg { width: 18px; height: 18px; fill: none; stroke: var(--ink); stroke-width: 2; stroke-linecap: round; }\n\n/* ── hero ────────────────────────────────────────────────────────────────── */\n.own-minimax .mm-hero { position: relative; padding: clamp(56px, 8cqi, 96px) var(--gut) clamp(48px, 6cqi, 80px); text-align: center; }\n.own-minimax .mm-hero .mm-h1 { margin-top: 18px; }\n.own-minimax .mm-hero-sub { color: var(--steel); font-size: 18px; line-height: 1.5; max-width: 52ch; margin: 20px auto 0; }\n.own-minimax .mm-hero-cta { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; margin-top: 30px; }\n.own-minimax .mm-terminal { max-width: 720px; margin: 48px auto 0; text-align: left; background: var(--primary); border-radius: 16px; overflow: hidden; box-shadow: rgba(0,0,0,.08) 0px 0px 22px 0px; }\n.own-minimax .mm-term-head { display: flex; align-items: center; gap: 7px; padding: 12px 16px; background: #161616; border-bottom: 1px solid #262626; }\n.own-minimax .mm-term-dot { width: 10px; height: 10px; border-radius: 50%; background: #3a3a3a; }\n.own-minimax .mm-term-dot:nth-child(1) { background: var(--coral); }\n.own-minimax .mm-term-dot:nth-child(2) { background: #f7b928; }\n.own-minimax .mm-term-dot:nth-child(3) { background: var(--success-text); }\n.own-minimax .mm-term-name { margin-left: auto; font-family: var(--mono); font-size: 12px; color: #8e8e93; }\n.own-minimax .mm-term-body { margin: 0; padding: 20px; font-family: var(--mono); font-size: 13px; line-height: 1.7; color: #e6e6e6; overflow-x: auto; }\n.own-minimax .mm-term-body .mm-c { color: #9a9a9a; }\n.own-minimax .mm-term-body .mm-k { color: var(--magenta); }\n.own-minimax .mm-term-body .mm-s { color: #7cebcb; }\n.own-minimax .mm-term-foot { display: flex; align-items: center; gap: 8px; padding: 12px 20px; border-top: 1px solid #262626; font-family: var(--mono); font-size: 12px; color: #8e8e93; }\n.own-minimax .mm-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--success-text); }\n\n/* ── badges ───────────────────────────────────────────────────────────────── */\n.own-minimax .mm-badge { display: inline-flex; align-items: center; padding: 4px 10px; border-radius: 9999px; font-size: 12px; font-weight: 600; line-height: 1.4; }\n.own-minimax .mm-badge-new { background: var(--coral); color: #fff; }\n.own-minimax .mm-badge-beta { background: var(--blue-200); color: var(--blue-deep); }\n.own-minimax .mm-badge-code { display: inline-flex; padding: 2px 6px; border-radius: 6px; background: var(--blue-200); color: var(--blue-deep); font-family: var(--mono); font-size: 13px; font-weight: 600; }\n\n/* ── sections ───────────────────────────────────────────────────────────── */\n.own-minimax .mm-sec { padding: clamp(48px, 6cqi, 80px) var(--gut); }\n.own-minimax .mm-sec-head { max-width: 680px; margin-bottom: 40px; }\n.own-minimax .mm-sec-head.mm-center { margin-left: auto; margin-right: auto; text-align: center; }\n.own-minimax .mm-sec-head .mm-lead { margin-top: 14px; }\n.own-minimax .mm-cards { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }\n.own-minimax .mm-pcard { position: relative; min-height: 300px; border-radius: 32px; padding: 32px; color: #fff; display: flex; flex-direction: column; justify-content: flex-end; overflow: hidden; }\n.own-minimax .mm-pcard::before { content: ''; position: absolute; inset: 0; background: radial-gradient(90% 80% at 80% 8%, rgba(255,255,255,.35), transparent 60%); pointer-events: none; }\n.own-minimax .mm-pcard::after { content: ''; position: absolute; inset: 0; background: linear-gradient(0deg, rgba(0,0,0,.52) 0%, rgba(0,0,0,.18) 42%, transparent 66%); pointer-events: none; }\n.own-minimax .mm-pcard-coral { background: linear-gradient(160deg, #ff7a4d 0%, var(--coral) 45%, #c72d0d 100%); }\n.own-minimax .mm-pcard-magenta { background: linear-gradient(160deg, #f58fd6 0%, var(--magenta) 45%, #9c2f79 100%); }\n.own-minimax .mm-pcard-blue { background: linear-gradient(160deg, #4d7ff5 0%, var(--blue) 45%, #0d2f8f 100%); }\n.own-minimax .mm-pcard-purple { background: linear-gradient(160deg, #c08bfa 0%, var(--purple) 45%, #6a25b0 100%); }\n.own-minimax .mm-pcard .mm-badge { position: absolute; top: 24px; right: 24px; }\n.own-minimax .mm-pcard-name { position: relative; font-weight: 600; font-size: clamp(30px, 3cqi, 44px); line-height: 1.1; letter-spacing: -1.5px; }\n.own-minimax .mm-pcard-tag { position: relative; margin-top: 8px; font-size: 14px; line-height: 1.5; color: rgba(255,255,255,.82); }\n.own-minimax .mm-ai-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; margin-top: 20px; }\n.own-minimax .mm-tile { display: block; text-decoration: none; color: inherit; background: var(--canvas); border: 1px solid var(--hairline); border-radius: 24px; padding: 24px; transition: border-color .15s; }\n.own-minimax .mm-tile:hover { border-color: var(--ink); }\n.own-minimax .mm-tile-art { display: block; height: 90px; border-radius: 16px; margin-bottom: 18px; }\n.own-minimax .mm-art-a { background: linear-gradient(135deg, #ffe3d6, #ffb59a); }\n.own-minimax .mm-art-b { background: linear-gradient(135deg, #e6d6ff, #c3a3f5); }\n.own-minimax .mm-art-c { background: linear-gradient(135deg, #d6ecff, #9ec9f5); }\n.own-minimax .mm-art-d { background: linear-gradient(135deg, #d6fff0, #8fe6cd); }\n.own-minimax .mm-tile-title { font-weight: 600; font-size: 20px; line-height: 1.4; }\n.own-minimax .mm-tile-desc { margin-top: 6px; font-size: 14px; line-height: 1.5; color: var(--steel); }\n\n/* feature cards */\n.own-minimax .mm-feature-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }\n.own-minimax .mm-card { background: var(--canvas); border: 1px solid var(--hairline); border-radius: 16px; padding: 24px; }\n.own-minimax .mm-icon { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 12px; background: var(--surface); margin-bottom: 18px; }\n.own-minimax .mm-icon svg { width: 22px; height: 22px; fill: none; stroke: var(--ink); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }\n.own-minimax .mm-card-title { font-weight: 600; font-size: 20px; line-height: 1.4; }\n.own-minimax .mm-card-desc { margin-top: 6px; font-size: 14px; line-height: 1.5; color: var(--steel); }\n\n/* stats */\n.own-minimax .mm-stats { padding: clamp(40px, 5cqi, 64px) var(--gut); background: var(--surface); }\n.own-minimax .mm-stat-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; }\n.own-minimax .mm-stat b { display: block; font-weight: 600; font-size: clamp(30px, 3.4cqi, 40px); line-height: 1.2; letter-spacing: -1px; }\n.own-minimax .mm-stat span { display: block; margin-top: 6px; font-size: 14px; color: var(--steel); }\n\n/* ── docs ─────────────────────────────────────────────────────────────────── */\n.own-minimax .mm-docs { background: var(--canvas); }\n.own-minimax .mm-docs-grid { display: grid; grid-template-columns: 200px minmax(0, 1fr) 180px; gap: 40px; align-items: start; }\n.own-minimax .mm-docs-side { position: sticky; top: 148px; display: grid; gap: 2px; }\n.own-minimax .mm-side-head { margin: 14px 0 4px; font-size: 12px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--stone); }\n.own-minimax .mm-side-link { display: block; padding: 8px 12px; border-radius: 6px; font-size: 14px; color: var(--charcoal-text); text-decoration: none; }\n.own-minimax .mm-side-link.is-active { background: var(--surface); color: var(--ink); font-weight: 500; }\n.own-minimax .mm-side-link:hover { background: var(--surface-soft); }\n.own-minimax .mm-docs-toc { position: sticky; top: 148px; display: grid; gap: 2px; }\n.own-minimax .mm-toc-link { display: block; padding: 8px 0; font-size: 14px; color: var(--steel); text-decoration: none; }\n.own-minimax .mm-toc-link.is-active { color: var(--ink); font-weight: 500; }\n.own-minimax .mm-docs-body { max-width: 720px; }\n.own-minimax .mm-code { border: 1px solid var(--hairline); border-radius: 8px; overflow: hidden; margin-bottom: 24px; }\n.own-minimax .mm-code-head { display: flex; align-items: center; justify-content: space-between; padding: 10px 14px; background: var(--surface); border-bottom: 1px solid var(--hairline); font-size: 13px; color: var(--steel); }\n.own-minimax .mm-copy { background: transparent; border: 0; color: var(--blue-deep); font-family: var(--font); font-size: 13px; font-weight: 500; cursor: pointer; }\n.own-minimax .mm-code-body { margin: 0; padding: 18px; background: var(--canvas); font-family: var(--mono); font-size: 13px; line-height: 1.7; color: var(--charcoal-text); overflow-x: auto; }\n.own-minimax .mm-code-body .mm-k { color: #9c2f79; }\n.own-minimax .mm-code-body .mm-s { color: #0e7a5c; }\n.own-minimax .mm-table { width: 100%; border-collapse: collapse; border: 1px solid var(--hairline); border-radius: 8px; overflow: hidden; }\n.own-minimax .mm-table th { text-align: left; padding: 12px 16px; background: var(--surface); font-size: 13px; font-weight: 600; color: var(--steel); }\n.own-minimax .mm-table td { padding: 14px 16px; font-size: 14px; border-top: 1px solid var(--hairline-soft); }\n.own-minimax .mm-table code { font-family: var(--mono); font-size: 13px; }\n\n/* ── pricing ─────────────────────────────────────────────────────────────── */\n.own-minimax .mm-tabs { display: flex; gap: 10px; justify-content: center; margin-bottom: 32px; flex-wrap: wrap; }\n.own-minimax .mm-pill { height: 36px; padding: 0 16px; border-radius: 9999px; border: 1px solid var(--hairline); background: var(--canvas); color: var(--steel); font-family: var(--font); font-size: 14px; font-weight: 500; cursor: pointer; }\n.own-minimax .mm-pill.is-active { background: var(--primary); color: #fff; border-color: var(--primary); }\n.own-minimax .mm-price-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; max-width: 1000px; margin: 0 auto; }\n.own-minimax .mm-price-card { position: relative; background: var(--canvas); border: 1px solid var(--hairline); border-radius: 16px; padding: 32px; display: flex; flex-direction: column; }\n.own-minimax .mm-price-featured { border: 2px solid var(--ink); box-shadow: rgba(0,0,0,.08) 0px 4px 6px 0px; }\n.own-minimax .mm-price-featured .mm-badge { position: absolute; top: -12px; left: 32px; }\n.own-minimax .mm-price { font-weight: 600; font-size: clamp(32px, 4cqi, 44px); letter-spacing: -1.5px; margin: 12px 0 20px; }\n.own-minimax .mm-price span { font-size: 14px; font-weight: 400; color: var(--steel); }\n.own-minimax .mm-price-list { list-style: none; margin: 0 0 26px; padding: 0; display: grid; gap: 12px; flex: 1; }\n.own-minimax .mm-price-list li { position: relative; padding-left: 26px; font-size: 14px; color: var(--charcoal-text); }\n.own-minimax .mm-price-list li::before { content: ''; position: absolute; left: 0; top: 5px; width: 14px; height: 8px; border-left: 2px solid var(--success-text); border-bottom: 2px solid var(--success-text); transform: rotate(-45deg); }\n\n/* ── cta ──────────────────────────────────────────────────────────────────── */\n.own-minimax .mm-cta { margin: 0 var(--gut) clamp(48px, 6cqi, 80px); background: linear-gradient(135deg, #ff7a4d, var(--coral) 55%, #c72d0d); color: #fff; border-radius: 32px; padding: clamp(44px, 6cqi, 80px) 32px; text-align: center; display: grid; gap: 26px; justify-items: center; }\n.own-minimax .mm-cta .mm-h2 { color: #fff; }\n\n/* ── footer ──────────────────────────────────────────────────────────────── */\n.own-minimax .mm-foot { background: var(--primary); color: #fff; padding: clamp(40px, 6cqi, 64px) var(--gut) 32px; }\n.own-minimax .mm-foot-top { display: grid; grid-template-columns: 220px 1fr; gap: 40px; }\n.own-minimax .mm-foot-brand { display: flex; align-items: center; gap: 10px; font-weight: 600; font-size: 18px; flex-wrap: wrap; }\n.own-minimax .mm-foot-brand .mm-logo-mark { width: 26px; height: 26px; border-radius: 8px; background: #fff; }\n.own-minimax .mm-foot-tag { flex-basis: 100%; margin-top: 10px; font-size: 14px; font-weight: 400; color: var(--muted); }\n.own-minimax .mm-foot-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }\n.own-minimax .mm-foot-col h3 { font-size: 14px; font-weight: 500; margin-bottom: 14px; color: #fff; }\n.own-minimax .mm-foot-col a { display: block; color: var(--muted); text-decoration: none; font-size: 14px; margin-bottom: 10px; }\n.own-minimax .mm-foot-col a:hover { color: #fff; }\n.own-minimax .mm-foot-bottom { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-top: 44px; padding-top: 20px; border-top: 1px solid #262626; font-size: 13px; color: var(--muted); }\n.own-minimax .mm-foot-links { display: flex; gap: 20px; }\n.own-minimax .mm-foot-links a { color: var(--muted); text-decoration: none; }\n.own-minimax .mm-foot-links a:hover { color: #fff; }\n\n/* ── responsive ──────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-minimax .mm-cards, .own-minimax .mm-ai-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-minimax .mm-feature-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-minimax .mm-stat-row { grid-template-columns: repeat(2, 1fr); row-gap: 28px; }\n  .own-minimax .mm-docs-grid { grid-template-columns: 1fr; gap: 24px; }\n  .own-minimax .mm-docs-side, .own-minimax .mm-docs-toc { position: static; }\n  .own-minimax .mm-docs-toc { display: none; }\n}\n@container frame (max-width: 760px) {\n  .own-minimax .mm-nav { top: 10px; gap: 12px; padding: 10px 14px; }\n  .own-minimax .mm-nav-links, .own-minimax .mm-nav-right .mm-btn { display: none; }\n  .own-minimax .mm-hamburger { display: inline-flex; margin-left: auto; }\n  .own-minimax .mm-price-grid { grid-template-columns: 1fr; }\n  .own-minimax .mm-foot-top { grid-template-columns: 1fr; gap: 28px; }\n  .own-minimax .mm-foot-grid { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 430px) {\n  .own-minimax .mm-cards, .own-minimax .mm-ai-grid, .own-minimax .mm-feature-grid, .own-minimax .mm-stat-row, .own-minimax .mm-foot-grid { grid-template-columns: 1fr; }\n  .own-minimax .mm-pcard { min-height: 220px; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-minimax *, .own-minimax *::before, .own-minimax *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — MiniMax own-layout behaviour ══════════════════════════════
   Registers window.OWN_LAYOUTS['minimax'].init(root). Handles the pricing tab
   pills, the copy-code button and the mobile menu toggle. Returns a cleanup
   that removes every listener and timer. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['minimax'] = {
    init: function (root) {
      var pills = Array.prototype.slice.call(root.querySelectorAll('[data-mm-tab]'));
      var copy = root.querySelector('.mm-copy');
      var code = root.querySelector('.mm-code-body');
      var burger = root.querySelector('[data-mm-menu]');
      var links = root.querySelector('.mm-nav-links');
      var timers = [];

      function onPill(e) {
        pills.forEach(function (p) {
          var on = p === e.currentTarget;
          p.classList.toggle('is-active', on);
          p.setAttribute('aria-selected', on ? 'true' : 'false');
        });
      }
      function onCopy() {
        if (!copy || !code) return;
        try { navigator.clipboard && navigator.clipboard.writeText(code.textContent); } catch (err) { /* ignore */ }
        var prev = copy.textContent;
        copy.textContent = 'Copied';
        timers.push(setTimeout(function () { if (copy) copy.textContent = prev; }, 1400));
      }
      function onBurger() {
        if (!links) return;
        var open = links.getAttribute('data-open') === '1';
        links.setAttribute('data-open', open ? '0' : '1');
        links.style.display = open ? '' : 'grid';
        links.style.position = 'absolute';
        links.style.top = '64px';
        links.style.left = '12px';
        links.style.right = '12px';
        links.style.margin = '0';
        links.style.padding = '14px';
        links.style.gap = '4px';
        links.style.background = '#fff';
        links.style.border = '1px solid var(--hairline)';
        links.style.borderRadius = '12px';
        links.style.boxShadow = 'rgba(0,0,0,.08) 0px 4px 6px 0px';
        links.style.zIndex = '40';
      }

      pills.forEach(function (p) { p.addEventListener('click', onPill); });
      if (copy) copy.addEventListener('click', onCopy);
      if (burger) burger.addEventListener('click', onBurger);

      return function cleanup() {
        pills.forEach(function (p) { p.removeEventListener('click', onPill); });
        if (copy) copy.removeEventListener('click', onCopy);
        if (burger) burger.removeEventListener('click', onBurger);
        timers.forEach(clearTimeout);
        if (links) { links.removeAttribute('style'); links.removeAttribute('data-open'); }
      };
    }
  };
})();
